import numpy as np
from copy import deepcopy
# physical long-ladder interaction response
L=8;P=2*L;h=np.zeros((P,P),complex);u=np.zeros((P,P));du=np.zeros((P,P));bonds=[]
for i in range(P):
 for j in range(i+1,P):
  if abs(i//2-j//2)+abs(i%2-j%2)==1:h[i,j]=h[j,i]=-1.
for x in range(L):
 if x%4==0:bonds.extend([(2*x,2*x+2),(2*x+1,2*x+3)])
 elif x%4 in (2,3):bonds.append((2*x,2*x+1))
e=1.9*np.where(np.random.default_rng(49273).uniform(-1,1,8)<0,-1.,1.)
