gauge=np.exp(1j*np.arange(P)*0.0);h=gauge[:,None]*h*gauge.conj()[None,:]
args=(np.stack((np.stack((h,u)),np.stack((np.zeros_like(h),du)))),P//3)
assert np.allclose(sector_density_pair(*deepcopy(args)), target)

